// The six MC68030 exception stack frames -- UM Table 8-6 -- the special status
// word of UM figure 8-9, and the offsets this design keeps its own state at
// inside the long frame.
//
// One wrong offset here is a silent demand-paging failure: the frame would be
// written correctly enough to pass its own format check and read back one word
// out. tools/ucode/frames.py is the single place any of these numbers exists.

`ifndef RD68031_FRAME_PKG_SV
`define RD68031_FRAME_PKG_SV

package rd68031_frame_pkg;

  // ==========================================================================
  // Frame sizes, in bytes, as the stack pointer must be adjusted by
  // ==========================================================================
  localparam int FRAME_0_BYTES = 8;   // four-word, 4 words
  localparam int FRAME_1_BYTES = 8;   // throwaway four-word, 4 words
  localparam int FRAME_2_BYTES = 12;   // six-word, 6 words
  localparam int FRAME_9_BYTES = 20;   // coprocessor midinstruction, 10 words
  localparam int FRAME_A_BYTES = 32;   // short bus fault, 16 words
  localparam int FRAME_B_BYTES = 92;   // long bus fault, 46 words

  // ==========================================================================
  // Architecturally named fields -- UM Table 8-6
  //
  // OFF is the byte offset from the stack pointer; a field present in more than
  // one frame is at the same offset in each, which is what makes one set of
  // constants right for all of them.
  // ==========================================================================
  localparam int OFF_SR            = 'h00;   // 1 word, status register
  localparam int OFF_PC            = 'h02;   // 2 words, program counter
  localparam int OFF_FMTVEC        = 'h06;   // 1 word, format and vector offset
  localparam int OFF_INSTR_ADDR    = 'h08;   // 2 words, instruction address
  localparam int OFF_SCANPC        = 'h02;   // 2 words, scan program counter
  localparam int OFF_OPWORD        = 'h0E;   // 1 word, operation word
  localparam int OFF_EA            = 'h10;   // 2 words, effective address
  localparam int OFF_SSW           = 'h0A;   // 1 word, special status word
  localparam int OFF_STAGE_C       = 'h0C;   // 1 word, instruction pipe stage C
  localparam int OFF_STAGE_B       = 'h0E;   // 1 word, instruction pipe stage B
  localparam int OFF_DFA           = 'h10;   // 2 words, data cycle fault address
  localparam int OFF_DOB           = 'h18;   // 2 words, data output buffer
  localparam int OFF_STAGE_B_ADDR  = 'h24;   // 2 words, stage B address
  localparam int OFF_DIB           = 'h2C;   // 2 words, data input buffer

  // ==========================================================================
  // The version number -- UM 8.1.8 and 8.1.13
  //
  // "The version number is located in the most significant nibble (bits 15-12)
  // of the word at location SP+$36 in the long stack frame." RTE compares it
  // with its own and takes a format error if they differ, which is the contract
  // that makes this design's private encoding of the internal words legitimate.
  // It is also why the SHORT frame, which has no version field, carries none of
  // them. See doc/manual-contradictions.md for the figure that draws it at $38.
  // ==========================================================================
  localparam int         OFF_VERSION  = 'h36;
  localparam int         VERSION_HI   = 15;
  localparam int         VERSION_LO   = 12;
  localparam logic [3:0] FRAME_VERSION = 4'h3;

  // ==========================================================================
  // The formats RTE accepts -- UM 8.4, "the MC68030 provides six different
  // stack frames". Bit n set means format $n is valid; any other is a format
  // error, vector 14 -- UM 8.1.8.
  // ==========================================================================
  localparam logic [15:0] FORMATS_VALID = 16'h0E07;

  // ==========================================================================
  // The special status word -- UM 8.2.1, figure 8-9
  //
  // The bits marked X, "for internal use only", carry nothing in this design:
  // they are written as zero and RTE ignores them -- doc/ssw.md.
  // ==========================================================================
  localparam int SSW_FC       = 15;   // fault on stage C of the instruction pipe
  localparam int SSW_FB       = 14;   // fault on stage B of the instruction pipe
  localparam int SSW_RC       = 13;   // rerun flag for stage C
  localparam int SSW_RB       = 12;   // rerun flag for stage B
  localparam int SSW_DF       = 8;   // fault/rerun flag for the data cycle
  localparam int SSW_RM       = 7;   // read-modify-write on the data cycle
  localparam int SSW_RW       = 6;   // read/write for the data cycle: 1 = read, 0 = write
  localparam int SSW_SIZE_HI  = 5;   // size code for the data cycle -- UM Table 7-2
  localparam int SSW_SIZE_LO  = 4;
  localparam int SSW_FCODE_HI = 2;   // the address space of the data cycle
  localparam int SSW_FCODE_LO = 0;
  localparam logic [15:0] SSW_INTERNAL = 16'h0E08;   // the X bits

  // ==========================================================================
  // This design's own state, in the long frame's internal words
  //
  // 492 bits available, 369 used, 0 reserved for M8-M11, 7 words spare.
  // Recompute this whenever something is added: doc/checkpoint.md carries the
  // same table, printed from the same source.
  // ==========================================================================
  localparam int OFF_I_BYTES     = 'h08;   //  3 bits, residual byte count of the faulted operand
  localparam int I_BYTES_HI      = 2;
  localparam int I_BYTES_LO      = 0;
  localparam int OFF_I_NOTRACE   = 'h08;   //  1 bits, the trace pending for this instruction was cancelled
  localparam int I_NOTRACE_HI    = 4;
  localparam int I_NOTRACE_LO    = 4;
  localparam int OFF_I_EAPC      = 'h08;   //  1 bits, the base of the effective address under way is the PC
  localparam int I_EAPC_HI       = 6;
  localparam int I_EAPC_LO       = 6;
  localparam int OFF_I_OPSIZE    = 'h08;   //  2 bits, the operand size the dispatching microword resolved
  localparam int I_OPSIZE_HI     = 8;
  localparam int I_OPSIZE_LO     = 7;
  localparam int OFF_I_EADST     = 'h08;   //  1 bits, the effective address under way is a MOVE destination
  localparam int I_EADST_HI      = 9;
  localparam int I_EADST_LO      = 9;
  localparam int OFF_I_TRMODE    = 'h36;   //  2 bits, the trace mode this instruction began with
  localparam int I_TRMODE_HI     = 2;
  localparam int I_TRMODE_LO     = 1;
  localparam int OFF_I_FLOW      = 'h36;   //  1 bits, this instruction has changed the flow
  localparam int I_FLOW_HI       = 3;
  localparam int I_FLOW_LO       = 3;
  localparam int OFF_I_PC_KEPT   = 'h36;   //  1 bits, pc_prev was taken at a flush, not at the decode
  localparam int I_PC_KEPT_HI    = 4;
  localparam int I_PC_KEPT_LO    = 4;
  localparam int OFF_I_PC_PREV   = 'h46;   // 32 bits, the address of the instruction before this one
  localparam int I_PC_PREV_HI    = 31;
  localparam int I_PC_PREV_LO    = 0;
  localparam int OFF_I_DVALID    = 'h08;   //  1 bits, stage D holds an instruction word
  localparam int I_DVALID_HI     = 15;
  localparam int I_DVALID_LO     = 15;
  localparam int OFF_I_UPC       = 'h14;   // 16 bits, the micro-address to resume at
  localparam int I_UPC_HI        = 15;
  localparam int I_UPC_LO        = 0;
  localparam int OFF_I_STAGE_D   = 'h16;   // 16 bits, the instruction word being decoded
  localparam int I_STAGE_D_HI    = 15;
  localparam int I_STAGE_D_LO    = 0;
  localparam int OFF_I_T0        = 'h1C;   // 32 bits, working register
  localparam int I_T0_HI         = 31;
  localparam int I_T0_LO         = 0;
  localparam int OFF_I_T1        = 'h20;   // 32 bits, working register
  localparam int I_T1_HI         = 31;
  localparam int I_T1_LO         = 0;
  localparam int OFF_I_T2        = 'h28;   // 32 bits, working register
  localparam int I_T2_HI         = 31;
  localparam int I_T2_LO         = 0;
  localparam int OFF_I_T3        = 'h30;   // 32 bits, working register
  localparam int I_T3_HI         = 31;
  localparam int I_T3_LO         = 0;
  localparam int OFF_I_XW        = 'h34;   // 16 bits, the extension-word latch
  localparam int I_XW_HI         = 15;
  localparam int I_XW_LO         = 0;
  localparam int OFF_I_EA_LATCH  = 'h38;   // 32 bits, the address output buffer
  localparam int I_EA_LATCH_HI   = 31;
  localparam int I_EA_LATCH_LO   = 0;
  localparam int OFF_I_EA_SAVE   = 'h3C;   // 32 bits, the copy of it taken at the fault
  localparam int I_EA_SAVE_HI    = 31;
  localparam int I_EA_SAVE_LO    = 0;
  localparam int OFF_I_PC_FETCH  = 'h40;   // 32 bits, the next long word the pipe will fetch
  localparam int I_PC_FETCH_HI   = 31;
  localparam int I_PC_FETCH_LO   = 0;
  localparam int OFF_I_LINK      = 'h44;   // 16 bits, the return address of the subroutine under way
  localparam int I_LINK_HI       = 15;
  localparam int I_LINK_LO       = 0;
  localparam int OFF_I_CPRIM     = 'h4A;   // 16 bits, the coprocessor response primitive being served
  localparam int I_CPRIM_HI      = 15;
  localparam int I_CPRIM_LO      = 0;
  localparam int OFF_I_POSTED    = 'h08;   //  1 bits, the faulted access was a posted write, which RTE reruns by itself
  localparam int I_POSTED_HI     = 5;
  localparam int I_POSTED_LO     = 5;
  localparam int OFF_I_IRQLVL    = 'h08;   //  3 bits, the level of the interrupt being taken
  localparam int I_IRQLVL_HI     = 12;
  localparam int I_IRQLVL_LO     = 10;
  localparam int OFF_I_RMWUPC    = 'h52;   // 16 bits, the micro-address the read-modify-write under way starts again at
  localparam int I_RMWUPC_HI     = 15;
  localparam int I_RMWUPC_LO     = 0;

endpackage

`endif
